import * as React from "react";
import { Link } from "gatsby";
import { StaticQuery, graphql } from "gatsby";
import { Label, Image, Header, Grid, Card, List, Container, Feed, Segment, Comment } from "semantic-ui-react";
import { MarkdownRemarkConnection, ImageSharp } from "../graphql-types";
import BlogTitle from "../components/BlogTitle";
import TagsCard from "../components/TagsCard/TagsCard";
import BlogPagination from "../components/BlogPagination/BlogPagination";
import { get } from "lodash";
import {withLayout, LayoutProps} from "../components/Layout";
import { MarkdownRemark } from "../graphql-types";

interface BlogProps extends LayoutProps {
  data: {
    tags: MarkdownRemarkConnection;
    posts: MarkdownRemarkConnection;
  };
  pageContext: {
    tag?: string; // only set into `templates/tags-pages.tsx`
  };
}

const BlogPage = (props: BlogProps) => {
  const tags = props.data.tags.group;
  const posts = props.data.posts.edges;
  const { pathname } = props.location;
  const pageCount = Math.ceil(props.data.posts.totalCount / 10);

  // TODO export posts in a proper component
  const Posts = (
    <Container>
        <Card.Group>
          {posts.map(({ node }: {node: MarkdownRemark}) => {
            const { frontmatter, timeToRead, fields: { slug }, html } = node;
            const avatar = frontmatter.author.avatar.children[0] as ImageSharp;
            const cover = get(frontmatter, "image.children.0.fixed", {});
            const taglabels = get(frontmatter, "tags", [])
            .map((tag) => <Label key={tag}><Link to={`/blog/tags/${tag}/`}>{tag}</Link></Label>);

            const extra = (
              <Comment.Group>
                <Comment>
                  <Comment.Avatar
                    src={avatar.fixed.src}
                    srcSet={avatar.fixed.srcSet}
                  />
                  <Comment.Content>
                    <Comment.Author style={{ fontWeight: 400 }}>
                      {frontmatter.author.id}
                    </Comment.Author>
                    <Comment.Metadata style={{ margin: 0 }}>
                      {frontmatter.updatedDate} - {timeToRead} min read
                  </Comment.Metadata>
                  </Comment.Content>
                </Comment>
              </Comment.Group>
            );

            const description = (
              <Card.Description>
                <div dangerouslySetInnerHTML={{__html: html}} />
                <br />
                <Link to={slug}>Read more…</Link>
              </Card.Description>
            );

            return (
              <Card fluid>
                {cover.src && <Image {...cover} fluid />}
                <Card.Content>
                  <Card.Header>
                    <Link to={slug}>{frontmatter.title}</Link>
                  </Card.Header>
                  <Card.Meta>
                  {frontmatter.author.id} - {frontmatter.author.bio} -
                  {" "}{timeToRead} min. read <div style={{float: "right"}}>{taglabels}</div>
                  </Card.Meta>
                </Card.Content>
                <Card.Content description>
                  <div dangerouslySetInnerHTML={{
                            __html: html,
                          }} />
                </Card.Content>
              </Card>
            );

          })}
      </Card.Group>
    </Container>
  );

  return (
    <Container>
      {/* Title */}
      {/*<BlogTitle />*/}

      {/* Content */}
      <Grid columns="equal" stackable>
        <Grid.Column width={12}>
          <Container text>{Posts}</Container>
        </Grid.Column>
        <Grid.Column width={4}>
          <TagsCard Link={Link} tags={tags} tag={props.pageContext.tag} />
        </Grid.Column>
      </Grid>
      <BlogPagination Link={Link} pathname={pathname} pageCount={pageCount} />
    </Container>
  );
};

export default withLayout(BlogPage);

export const pageQuery = graphql`
query PageBlog {
  # Get tags
  tags: allMarkdownRemark(filter: {frontmatter: {draft: {ne: true}}}) {
    group(field: frontmatter___tags) {
      fieldValue
      totalCount
    }
  }

  # Get posts
  posts: allMarkdownRemark(
    sort: { order: DESC, fields: [frontmatter___updatedDate] },
    filter: {
      frontmatter: { draft: { ne: true } },
      fileAbsolutePath: { regex: "/blog/" }
    },
    limit: 10
  ) {
    totalCount
    edges {
      node {
        html
        timeToRead
        fields {
          slug
        }
        frontmatter {
          tags
          title
          updatedDate(formatString: "DD MMMM, YYYY")
          image {
          	children {
              ... on ImageSharp {
                fixed(width: 700, height: 100) {
                  src
                  srcSet
                }
              }
            }
          }
          author {
            id
            bio
            avatar {
              children {
                ... on ImageSharp {
                  fixed(width: 35, height: 35) {
                    src
                    srcSet
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
`;
